using System.Text.Json; using CubeSolverPro.Core.Statistics;
namespace CubeSolverPro.Core.Data;
public static class Transfer { public const string ExportFormat="cube-solver-pro-export"; public const int ExportVersion=1; static readonly JsonSerializerOptions Json=new(){PropertyNameCaseInsensitive=true,WriteIndented=true}; static long Now()=>DateTimeOffset.UtcNow.ToUnixTimeMilliseconds(); public static string NewId(string prefix)=>$"{prefix}-{Now():x}-{Guid.NewGuid():N}"[..Math.Min(prefix.Length+1+13+1+6,prefix.Length+1+13+1+32)];
 public static ExportFile BuildExport(IEnumerable<Session>s,IEnumerable<Solve>v,IEnumerable<TrainerStat>t,Settings? settings=null)=>new(ExportFormat,ExportVersion,Now(),s.ToList(),v.ToList(),t.ToList(),settings); public static string Serialize(ExportFile f)=>JsonSerializer.Serialize(f,Json);
 public static ImportResult ParseImport(string text){JsonDocument d;try{d=JsonDocument.Parse(text);}catch(JsonException){throw new FormatException("That file is not valid JSON.");}using(d){var root=d.RootElement;if(root.ValueKind!=JsonValueKind.Object)throw new FormatException("That file does not contain any data.");if(root.TryGetProperty("format",out var fmt)&&fmt.GetString()==ExportFormat){var file=JsonSerializer.Deserialize<ExportFile>(text,Json)!;var ids=file.Sessions.Where(x=>ValidPuzzle(x.Puzzle)).Select(x=>x.Id).ToHashSet();return new(file.Sessions.Where(x=>ids.Contains(x.Id)).ToList(),file.Solves.Where(x=>ids.Contains(x.SessionId)&&x.TimeMs>=0).ToList(),file.TrainerStats.Where(x=>!string.IsNullOrEmpty(x.Id)).ToList(),file.Settings,"cube-solver-pro");}var keys=root.EnumerateObject().Where(x=>System.Text.RegularExpressions.Regex.IsMatch(x.Name,"^session\\d+$")).ToArray();if(keys.Length==0)throw new FormatException("That file is not a Cube Solver Pro or csTimer export.");var sessions=new List<Session>();var solves=new List<Solve>();foreach(var p in keys){if(p.Value.ValueKind!=JsonValueKind.Array)continue;var sid=NewId("session");var earliest=Now();foreach(var row in p.Value.EnumerateArray()){if(row.ValueKind!=JsonValueKind.Array||row.GetArrayLength()<2||row[0].ValueKind!=JsonValueKind.Array)continue;var pair=row[0];if(pair.GetArrayLength()<2||!pair[1].TryGetInt64(out var time)||time<0)continue;var penalty=pair[0].GetInt32() switch{-1=>Penalty.Dnf,2000=>Penalty.Plus2,_=>Penalty.None};var created=row.GetArrayLength()>3&&row[3].TryGetInt64(out var sec)?sec*1000:Now();earliest=Math.Min(earliest,created);solves.Add(new(NewId("solve"),sid,"333",row[1].GetString()??"",time,penalty,created,row.GetArrayLength()>2?row[2].GetString():null));}sessions.Add(new(sid,$"Imported session {p.Name[7..]}","333",earliest));}return new(sessions,solves,[],null,"cstimer");}}
 static bool ValidPuzzle(string x)=>new[]{"222","333","444","555","666","777"}.Contains(x);
}
